package lauberhorn

import jsteward.blocks.DutSimFunSuite
import spinal.core.sim._

/** Vectors are generated by compiling the actual VM policy, through the Nix
  * scheduler-policy check. Stateful arbitration is compared across all rows. */
class SchedulerPolicyAgreementSim extends DutSimFunSuite[SchedulerAllocation] {
  val dut = Config.sim.compile(new SchedulerAllocation(16, 4, 16))
  test("vm-and-rtl-stateful-allocation-agree") { implicit dut =>
    val path = os.Path(sys.env.getOrElse("LH_SCHEDULER_VECTORS", "out/scheduler-policy-vectors.txt"), os.pwd)
    assume(os.exists(path), "run the Nix scheduler-policy check to build VM policy vectors")
    SimTimeout(100000)
    dut.clockDomain.forkStimulus(4)
    dut.io.enabled #= 0; dut.io.deadlines #= 0
    dut.io.available #= 0; dut.io.ready #= 0
    dut.io.arrival.valid #= false; dut.io.arrival.payload #= 0; dut.io.arrivalFill #= 0
    dut.io.maximum.foreach(_ #= 0); dut.io.fill.foreach(_ #= 0); dut.io.owner.foreach(_ #= 0)
    dut.clockDomain.waitSampling(10); sleep(1)
    val vectors = os.read.lines(path)
    assert(vectors.length == 4096)
    for ((row, index) <- vectors.zipWithIndex) {
      val values = row.split(" ").map(_.toInt)
      assert(values.length == 47)
      dut.io.arrival.valid #= (values(0) != 0)
      dut.io.arrival.payload #= values(0); dut.io.arrivalFill #= values(1)
      dut.io.enabled #= values(2); dut.io.deadlines #= values(3)
      dut.io.available #= values(4); dut.io.ready #= values(5)
      for (d <- 0 to 16) { dut.io.maximum(d) #= values(6 + d); dut.io.fill(d) #= values(23 + d) }
      for (c <- 0 until 4) dut.io.owner(c) #= values(40 + c)
      sleep(1)
      assert(dut.io.grant.valid.toBoolean == (values(45) >= 0), s"valid mismatch at vector $index")
      if (values(45) >= 0) {
        assert(dut.io.grant.slot.toInt == values(44), s"domain mismatch at vector $index")
        assert(dut.io.grant.core.toInt == values(45), s"core mismatch at vector $index")
        assert(dut.io.grant.reason.toEnum.position == values(46), s"reason mismatch at vector $index")
      }
      dut.clockDomain.waitSampling(); sleep(1)
    }
  }
}
